package server

const pageTemplate = `{{define "page"}}<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>{{if .Chapter}}{{.Root.Title}} · {{end}}{{.Saga.Manifest.Title}} · Review Saga</title>
<style>` + pageStyles + `</style><script src="/app.js" defer></script></head><body>
<header class="topbar"><div class="brand">Review Saga</div><div class="view-tabs" aria-label="Review workspace"><button class="view-tab active" data-view-tab="saga">Saga</button><button class="view-tab" data-view-tab="code">Code Diff</button></div><label class="reviewer"><span>Reviewer</span><input id="reviewer-name" autocomplete="name" placeholder="Your name"></label><div class="top-meta" hidden>{{len .Files}} files · {{.ReviewedFiles}} reviewed</div></header>
<div class="shell" data-shell><aside class="sidebar" id="changed-files-panel"><a class="sidebar-title" href="/">{{.Saga.Manifest.Title}}</a><div class="saga-side"><div class="side-label">Chapters</div>{{template "chapter-index" .Chapters}}{{if .Chapter}}<div class="side-label">On this page</div><nav>{{template "nav" .Root}}</nav>{{end}}</div><div class="code-side" hidden><div class="side-label">Changed files</div><div class="tree-tools"><input type="search" data-file-filter placeholder="Filter paths" aria-label="Filter changed files"><button type="button" class="tree-close" data-toggle-tree aria-label="Hide changed files">Hide</button></div><label class="tree-filter-check"><input type="checkbox" data-hide-reviewed> Hide reviewed files</label>{{if .Code}}<p class="tree-summary" data-tree-summary>{{.Code.Tree.ReviewedCount}} of {{.Code.Tree.FileCount}} reviewed · +{{.Code.Tree.Added}} −{{.Code.Tree.Deleted}}</p><div class="file-tree" role="tree" aria-label="Changed files">{{template "file-tree-nodes" .Code.Tree.Nodes}}</div><p class="tree-empty" data-tree-empty hidden>No files match this filter.</p>{{end}}</div></aside>
<main class="content"><div class="view active" data-view="saga">{{if .Error}}<div class="alert" role="alert"><strong>Review readiness check failed</strong>{{.Error}}</div>{{else if .Diagnostic}}<div class="alert" role="alert"><strong>Review readiness check failed</strong>{{.Diagnostic}}</div>{{end}}{{if .Overview}}<header class="page-heading"><div class="eyebrow">Overview</div><h2>{{.Saga.Manifest.Title}}</h2></header>{{template "overview" .Root}}<section class="chapter-index"><h2>Continue with a chapter</h2>{{template "chapter-index" .Chapters}}</section>{{else}}<nav class="breadcrumbs" aria-label="Breadcrumb"><a href="/">Overview</a> <span aria-hidden="true">/</span> <span>{{.Root.Title}}</span></nav>{{template "section" .Root}}{{end}}</div>
<div class="view" data-view="code"><div class="code-toolbar" aria-label="Code review layout"><button type="button" data-toggle-tree aria-controls="changed-files-panel" aria-pressed="true">Files</button><button type="button" data-layout="inline" aria-pressed="true">Inline</button><button type="button" data-layout="split" aria-pressed="false">Side by side</button><span class="spacer"></span><button type="button" data-toggle-related aria-controls="related-saga-panel" aria-pressed="true">Related saga</button></div><div class="code-workspace" data-code-workspace><div class="code-main"><div class="code-heading"><div><div class="side-label">Complete comparison</div><h2>Code Diff</h2></div><span class="metric">{{.ReviewedFiles}} / {{len .Files}} files reviewed</span></div>{{with .Code.SelectedFile}}{{template "file-diff" .}}{{else}}<div class="remaining">No product code changes in this comparison.</div>{{end}}</div>{{if .Code.SelectedFile}}<aside class="related-saga" id="related-saga-panel" aria-label="Related saga context"><div class="related-head"><h2>Related saga</h2><button type="button" data-toggle-related aria-label="Hide related saga">Hide</button></div>{{range .Code.RelatedSaga}}<section class="related-chapter"><a href="{{.Href}}">{{.Title}}</a>{{range .Fragments}}<a class="related-fragment" href="{{.Href}}"><strong>{{.Title}}</strong>{{if .Excerpt}}<span>{{.Excerpt}}</span>{{end}}</a>{{end}}</section>{{else}}<p>{{.Code.RelatedEmpty}}</p>{{end}}</aside>{{end}}</div></div></main></div>
<div class="annotation-toolbox" role="toolbar" aria-label="Annotation tools"><span class="tool-target" data-tool-target>No fragment selected</span><button type="button" data-tool="select" aria-pressed="true">Select</button><button type="button" data-tool="target" aria-pressed="false">Comment</button><button type="button" data-tool="text" aria-pressed="false">Highlight</button><button type="button" data-tool="rect" aria-pressed="false">Rectangle</button><button type="button" data-tool="draw" aria-pressed="false">Freehand</button></div>
<dialog class="dialog decision-dialog" aria-labelledby="decision-title"><div class="dialog-head"><h2 id="decision-title">Record a decision</h2><button type="button" data-close-decision aria-label="Close decision dialog">Close</button></div><form class="dialog-form" method="post" action="/api/review"><input type="hidden" name="target"><input type="hidden" name="author" class="session-author"><textarea name="body" placeholder="Optional review note"></textarea><div class="decision-actions"><button name="state" value="approved">Approve</button><button class="danger" name="state" value="rejected">Request changes</button><button class="btn-subtle" name="state" value="closed">Close review</button></div></form></dialog>
<form class="dialog annotation-compose" method="post" action="/api/thread" enctype="multipart/form-data"><input type="hidden" name="target"><input type="hidden" name="anchor"><input type="hidden" name="kind" value="comment"><input type="hidden" name="author" class="session-author"><div class="dialog-head"><h2>Comment on this fragment</h2><button type="button" data-close-annotation>Cancel</button></div><div class="dialog-form"><textarea name="body" placeholder="Start a review thread"></textarea><input type="file" name="attachment" accept="image/*,.svg,.html,.txt" multiple><button type="submit">Create thread</button></div></form>
<div class="drawer-backdrop" data-close-drawer></div><aside class="diff-drawer" aria-hidden="true" aria-label="Linked diffs"><div class="drawer-head"><div><div class="side-label">Attached code</div><h2>Linked diffs</h2></div><button type="button" data-close-drawer>Close</button></div><div class="drawer-body"></div></aside>
<form class="diff-compose" method="post" action="/api/thread" enctype="multipart/form-data"><input type="hidden" name="target"><input type="hidden" name="anchor"><input type="hidden" name="kind" value="comment"><input type="hidden" name="author" class="session-author"><div class="diff-compose-head"><strong>Comment on this change</strong><button type="button" data-close-diff-compose>Cancel</button></div><div class="diff-compose-fields"><textarea name="body" placeholder="What should the author know?"></textarea><button type="submit">Add to review</button><textarea class="replacement" name="replacement" placeholder="Replacement code"></textarea><input type="file" name="attachment" accept="image/*,.svg,.html,.txt" multiple></div></form>
</body></html>{{end}}

{{define "chapter-index"}}{{range .}}<details class="chapter-card {{if .Active}}active{{end}}"><summary><span class="chapter-title">{{.Title}}</span><span class="chapter-status">{{.Status}}</span></summary><div class="chapter-details"><span>{{.Summary}}</span><a class="btn" href="{{.URL}}">{{.Action}}</a></div></details>{{else}}<p>No chapters in this saga.</p>{{end}}{{end}}

{{define "file-tree-nodes"}}{{range .}}{{if eq .Kind "folder"}}<details data-tree-folder {{if .Expanded}}open{{end}}><summary role="treeitem"><span aria-hidden="true">▸</span><span>{{.Name}}</span><span class="counts">{{.ReviewedCount}}/{{.FileCount}}</span></summary><div role="group">{{template "file-tree-nodes" .Children}}</div></details>{{else}}<a role="treeitem" data-tree-file data-tree-path="{{.File.Path}}" data-reviewed="{{.File.Reviewed}}" class="{{if .File.Reviewed}}reviewed{{end}} {{if .File.Selected}}selected{{end}}" href="{{.File.Href}}" aria-current="{{if .File.Selected}}page{{else}}false{{end}}"><span class="tree-state" aria-label="{{if .File.Reviewed}}Reviewed{{else}}Not reviewed{{end}}">{{if .File.Reviewed}}✓{{else}}○{{end}}</span><code>{{.Name}}</code><span class="counts">+{{.File.Added}} −{{.File.Deleted}}</span></a>{{end}}{{end}}{{end}}

{{define "nav"}}<a href="#{{.DOMID}}">{{.Title}}</a>{{range .FragmentViews}}<a class="nav-child" href="#{{.DOMID}}">{{if .Title}}{{.Title}}{{else}}{{.ID}}{{end}}</a>{{end}}{{if .ChildViews}}<div class="nav-child">{{range .ChildViews}}{{template "nav" .}}{{end}}</div>{{end}}{{end}}
{{define "diff-icon"}}<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M8 3v12a4 4 0 0 0 4 4h4M5 6l3-3 3 3M13 16l3 3-3 3"/></svg>{{end}}
{{define "decision-button"}}<button class="icon-button" type="button" data-review-target="{{.Target}}" data-review-title="{{if .Title}}{{.Title}}{{else}}{{.ID}}{{end}}" aria-label="Review decisions for {{if .Title}}{{.Title}}{{else}}{{.ID}}{{end}}">⋯</button>{{end}}

{{define "overview"}}<section id="{{.DOMID}}">{{if .ReviewState}}<div class="review-status">{{.ReviewState}} by {{.ReviewAuthor}}</div>{{end}}<div class="section-actions">{{if .Changes}}<button class="btn-subtle diff-button" type="button" data-open-diffs="diffs-{{.DOMID}}">{{template "diff-icon"}} {{len .Changes}}</button>{{end}}{{template "decision-button" .}}</div>{{template "threads" .Threads}}{{range .FragmentViews}}{{template "fragment" .}}{{end}}{{if .Changes}}{{template "diff-template" .}}{{end}}</section>{{end}}
{{define "section"}}<section class="section {{.Kind}}" id="{{.DOMID}}"><div class="section-head"><h2>{{.Title}}</h2><div class="section-actions">{{if .Changes}}<button class="btn-subtle diff-button" type="button" data-open-diffs="diffs-{{.DOMID}}">{{template "diff-icon"}} {{len .Changes}}</button>{{end}}{{template "decision-button" .}}</div></div>{{if .ReviewState}}<div class="review-status">{{.ReviewState}} by {{.ReviewAuthor}}</div>{{end}}{{template "threads" .Threads}}{{range .FragmentViews}}{{template "fragment" .}}{{end}}{{if .Changes}}{{template "diff-template" .}}{{end}}{{range .ChildViews}}{{template "section" .}}{{end}}</section>{{end}}
{{define "diff-template"}}<template id="diffs-{{.DOMID}}"><div class="file-diff"><div class="file-head"><strong>{{.Title}}</strong><span class="counts">{{len .Changes}} changes</span></div><div class="diff-lines">{{range .Changes}}{{template "compact-diff-row" .}}{{end}}</div></div></template>{{end}}
{{define "fragment"}}<article class="fragment" id="{{.DOMID}}" data-target="{{.Target}}" data-fragment-title="{{if .Title}}{{.Title}}{{else}}{{.ID}}{{end}}" tabindex="0"><div class="fragment-head"><div><h3>{{if .Title}}{{.Title}}{{else}}{{.ID}}{{end}}</h3>{{if .ReviewState}}<div class="review-status">{{.ReviewState}} by {{.ReviewAuthor}}</div>{{end}}</div><div class="fragment-actions">{{if .Changes}}<button type="button" class="btn-subtle diff-button" data-open-diffs="diffs-{{.DOMID}}">{{template "diff-icon"}} {{len .Changes}}</button>{{end}}{{template "decision-button" .}}</div></div><div class="fragment-stage">{{if .Markdown}}<div class="fragment-markdown" data-selectable>{{.Markdown}}</div>{{else if .Plain}}<pre class="plain" data-selectable>{{.Plain}}</pre>{{else if .Interactive}}<iframe class="fragment-frame" sandbox="allow-scripts" src="{{.URL}}" title="{{.Title}}"></iframe>{{else if .Image}}<img class="fragment-image" src="{{.URL}}" alt="{{.Title}}">{{else}}<a href="{{.URL}}">Open fragment</a>{{end}}<svg class="review-overlay" viewBox="0 0 1000 1000" preserveAspectRatio="none">{{range .Threads}}{{range .Anchor.Shapes}}{{if eq .Type "rect"}}<rect class="annotation" x="{{coord .X}}" y="{{coord .Y}}" width="{{coord .Width}}" height="{{coord .Height}}"/>{{else if eq .Type "ellipse"}}<ellipse class="annotation" cx="{{coord .X}}" cy="{{coord .Y}}" rx="{{coord .Width}}" ry="{{coord .Height}}"/>{{else if eq .Type "line"}}<line class="annotation path" x1="{{coord .X}}" y1="{{coord .Y}}" x2="{{coord .Width}}" y2="{{coord .Height}}"/>{{else if eq .Type "path"}}<polyline class="annotation path" points="{{points .Points}}"/>{{end}}{{end}}{{end}}</svg></div>{{template "threads" .Threads}}{{if .Changes}}{{template "diff-template" .}}{{end}}</article>{{end}}

{{define "file-diff"}}<article class="file-diff" id="{{.ID}}" data-file-path="{{.Path}}"><header class="file-head"><code>{{.Path}}</code>{{if .Reviewed}}<span class="reviewed-badge">✓ Reviewed{{if .Reviewer}} by {{.Reviewer}}{{end}}</span>{{end}}<span class="counts">+{{.Added}} −{{.Deleted}}</span><details class="file-review-menu"><summary>{{if .Reviewed}}Reviewed{{else}}Review file{{end}}</summary><form class="file-review" method="post" action="/api/diff-review"><input type="hidden" name="uri" value="{{.URI}}"><input type="hidden" name="file" value="{{.ID}}"><input type="hidden" name="author" class="session-author"><p>{{if .Reviewed}}Move this file back to the review queue.{{else}}Mark this file complete.{{end}}</p><button name="state" value="{{if .Reviewed}}unreviewed{{else}}reviewed{{end}}">{{if .Reviewed}}Unmark reviewed{{else}}Mark reviewed{{end}}</button></form></details></header><div class="diff-surface" data-diff-surface data-layout="inline"><div class="diff-column-head" aria-hidden="true"><span class="inline-column">Old</span><span class="inline-column">New</span><span class="inline-column">±</span><span class="inline-column">Code</span><span class="inline-column">Actions</span><span class="split-label">Before</span><span class="split-label">After</span></div><div class="diff-lines" data-diff-body>{{range .Lines}}{{template "diff-surface-row" .}}{{end}}</div><div class="diff-selection-toolbar" data-selection-toolbar role="toolbar" aria-label="Selected diff lines"><span data-selection-label></span><button type="button" data-selection-action="comment">Comment</button><button type="button" data-selection-action="suggestion">Suggest</button><button type="button" data-selection-clear>Clear</button></div></div></article>{{end}}

{{define "diff-surface-row"}}{{if eq .Kind "context"}}<div class="diff-row context" data-context-row role="row" aria-label="Unchanged line {{.NewLine}}"><span class="line-no">{{.OldLine}}</span><span class="line-no">{{.NewLine}}</span><span class="sign" aria-hidden="true">·</span><code class="code-line" data-code>{{.Content}}</code><span></span></div>{{else if eq .Kind "event"}}<div class="diff-row event" role="row"><span class="line-no">•</span><span class="line-no">•</span><span class="sign" aria-hidden="true">↳</span><span class="code-line">{{.Event}} {{if .OldPath}}{{.OldPath}} → {{.NewPath}}{{else}}{{.Path}}{{end}}</span>{{with .Atom}}<span class="line-actions"><button type="button" data-diff-action="comment" data-diff-ref="{{.URI}}" data-target="{{.Target}}">Comment</button></span>{{template "diff-threads" .Threads}}{{end}}</div>{{else}}{{$atom := .Atom}}<div class="diff-row {{.Kind}} {{if $atom.Selected}}selected{{end}}" data-diff-row data-side="{{.Kind}}" data-line="{{if eq .Kind "old"}}{{.OldLine}}{{else}}{{.NewLine}}{{end}}" data-path="{{.Path}}" data-diff-ref="{{$atom.URI}}" data-target="{{$atom.Target}}" role="row" aria-label="{{if eq .Kind "old"}}Removed old line {{.OldLine}}{{else}}Added new line {{.NewLine}}{{end}}"><span class="line-no">{{if .OldLine}}{{.OldLine}}{{end}}</span><button class="line-select" type="button" data-line-select aria-label="Select {{if eq .Kind "old"}}removed line {{.OldLine}}{{else}}added line {{.NewLine}}{{end}}">{{if .NewLine}}{{.NewLine}}{{end}}</button><span class="sign" aria-hidden="true">{{if eq .Kind "old"}}−{{else}}+{{end}}</span><code class="code-line" data-code>{{.Content}}</code><span class="line-actions"><button type="button" data-diff-action="comment" data-diff-ref="{{$atom.URI}}" data-target="{{$atom.Target}}">Comment</button><button type="button" data-diff-action="suggestion" data-diff-ref="{{$atom.URI}}" data-target="{{$atom.Target}}" data-content="{{.Content}}">Suggest</button></span>{{template "diff-threads" $atom.Threads}}</div>{{end}}{{end}}
{{define "compact-diff-row"}}{{if eq .Kind "event"}}<div class="diff-row event"><span class="line-no">•</span><span class="line-no">•</span><span class="sign">↳</span><span class="code-line">{{.Event}} {{if .OldPath}}{{.OldPath}} → {{.NewPath}}{{else}}{{.Path}}{{end}}</span><span class="line-actions"><button type="button" data-diff-action="comment" data-diff-ref="{{.URI}}" data-target="{{.Target}}">Comment</button></span>{{template "diff-threads" .Threads}}</div>{{else}}<div class="diff-row {{.Side}}"><span class="line-no">{{if eq .Side "old"}}{{.Line}}{{end}}</span><span class="line-no">{{if eq .Side "new"}}{{.Line}}{{end}}</span><span class="sign">{{if eq .Side "new"}}+{{else}}−{{end}}</span><code class="code-line" data-code>{{.Content}}</code><span class="line-actions"><button type="button" data-diff-action="comment" data-diff-ref="{{.URI}}" data-target="{{.Target}}">Comment</button><button type="button" data-diff-action="suggestion" data-diff-ref="{{.URI}}" data-target="{{.Target}}" data-content="{{.Content}}">Suggest</button></span>{{template "diff-threads" .Threads}}</div>{{end}}{{end}}
{{define "diff-threads"}}{{if .}}<div class="diff-thread-wrap">{{template "threads" .}}</div>{{end}}{{end}}
{{define "threads"}}{{if .}}<div class="threads">{{range .}}{{$thread := .}}<article class="thread {{.State}} {{.Kind}}"><div class="thread-meta">{{.CreatedBy}} · {{.CreatedAt.Format "2006-01-02 15:04 MST"}} · {{if .Kind}}{{.Kind}}{{else}}{{.Anchor.Type}}{{end}} · {{.State}}</div>{{if .Anchor.Text}}<div class="text-anchor" data-text-target="{{.Target}}" data-exact="{{.Anchor.Text.Exact}}">“{{.Anchor.Text.Exact}}”</div>{{end}}{{if .Suggestion}}<code class="suggestion-code">{{.Suggestion.Replacement}}</code>{{end}}{{range $index,$message := .Messages}}<div class="message"><div class="thread-meta">{{$message.Author}} · {{$message.CreatedAt.Format "2006-01-02 15:04 MST"}}</div>{{range index $thread.MessageViews $index}}<div class="message-fragment">{{if .Markdown}}<div class="fragment-markdown">{{.Markdown}}</div>{{else if .Interactive}}<iframe class="fragment-frame" sandbox="allow-scripts" src="{{.URL}}"></iframe>{{else if .Image}}<img class="fragment-image" src="{{.URL}}" alt="attachment">{{else}}<pre class="plain">{{.Plain}}</pre>{{end}}</div>{{end}}</div>{{end}}<form class="reply" method="post" action="/api/reply" enctype="multipart/form-data"><input type="hidden" name="thread" value="{{.ID}}"><input type="hidden" name="target" value="{{.Target}}"><input type="hidden" name="author" class="session-author"><input name="body" placeholder="Reply"><button>Reply</button><input type="file" name="attachment" accept="image/*,.svg,.html,.txt" multiple></form><form class="thread-state" method="post" action="/api/thread-state"><input type="hidden" name="thread" value="{{.ID}}"><input type="hidden" name="target" value="{{.Target}}"><input type="hidden" name="author" class="session-author"><button name="state" value="{{if eq .State "resolved"}}open{{else}}resolved{{end}}">{{if eq .State "resolved"}}Reopen{{else}}Resolve{{end}}</button></form></article>{{end}}</div>{{end}}{{end}}`
